  const aliases = Object.freeze({"en":"en","en-us":"en","en-gb":"en","es":"es","pt":"pt-BR","pt-br":"pt-BR","zh":"zh-CN","zh-cn":"zh-CN","zh-hans":"zh-CN","zh-sg":"zh-CN","zh-tw":"zh-TW","zh-hant":"zh-TW","zh-hk":"zh-TW","zh-mo":"zh-TW","ja":"ja","ko":"ko","fr":"fr","de":"de","it":"it","nl":"nl","pl":"pl","tr":"tr","ru":"ru","uk":"uk","hi":"hi","id":"id","vi":"vi","th":"th","ar":"ar","da":"da"});
  let locale = 'en';
  let storageRevision = 0;
  const subscribers = new Set();

  function normalize(value) {
    const raw = String(value || '').replace(/_/g, '-');
    let candidate = raw;
    try { [candidate] = Intl.getCanonicalLocales(raw); } catch { return 'en'; }
    const aliased = aliases[candidate.toLowerCase()];
    if (aliased) return aliased;
    const exact = Object.keys(catalogs).find((id) => id.toLowerCase() === candidate.toLowerCase());
    if (exact) return exact;
    const base = candidate.split('-')[0].toLowerCase();
    return aliases[base] || Object.keys(catalogs).find((id) => id.toLowerCase() === base) || 'en';
  }

  function translateText(value) {
    if (typeof value !== 'string' || locale === 'en') return value;
    const leading = value.match(/^\s*/)?.[0] || '';
    const trailing = value.match(/\s*$/)?.[0] || '';
    const end = trailing.length ? value.length - trailing.length : value.length;
    const message = value.slice(leading.length, end);
    return catalogs[locale]?.[message] ? leading + catalogs[locale][message] + trailing : value;
  }

  function storageChanged(changes, areaName) {
    if (areaName && areaName !== 'local' || !changes?.[STORAGE_KEY]) return;
    storageRevision += 1;
    const next = normalize(changes[STORAGE_KEY].newValue);
    if (next === locale) return;
    locale = next;
    for (const subscriber of subscribers) subscriber({ locale, translateText });
  }

  async function initialize() {
    const startingRevision = storageRevision;
    browserApi.storage.onChanged.addListener(storageChanged);
    const stored = await browserApi.storage.local.get(STORAGE_KEY).catch(() => ({}));
    if (storageRevision === startingRevision) locale = normalize(stored?.[STORAGE_KEY]);
    return locale;
  }

  const ready = initialize();
  globalThis.HermesI18nContent = Object.freeze({
    getLocale: () => locale,
    ready,
    subscribe(subscriber) {
      if (typeof subscriber !== 'function') return () => {};
      subscribers.add(subscriber);
      return () => subscribers.delete(subscriber);
    },
    translateText,
  });
